  start({L1_TRAIL_BELL:1});a.abilities.place({x:260,y:450},12);const oldDamage=target(285,450);f.install({L1_TRAIL_BELL:1,A07:1});a.abilities.place({x:500,y:450},15);const newDamage=target(525,450);step(25);check('old and new trail damage freeze at respective deployment values',Math.abs(oldDamage.getData('hp')-9989.2)<1e-6&&Math.abs(newDamage.getData('hp')-9986.5)<1e-6,{old:oldDamage.getData('hp'),new:newDamage.getData('hp')});
